(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const vals = Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null && /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||'')).map(i=>i.value);
  const active = document.activeElement ? (document.activeElement.id || document.activeElement.tagName) : 'none';
  const visibleTxt = (document.body.innerText||'').replace(/\s+/g,' ').slice(0, 360);
  const disabled = Array.from(document.querySelectorAll('button')).filter(b=>/confirm\s*otp/i.test((b.innerText||'').replace(/\s+/g,' '))).map(b=>({dis: b.disabled, cls: (b.className||'').toString().slice(0,60)}));
  return JSON.stringify({vals, active, visibleTxt, disabled});
})()
